-- AI Picks: seed the backtest evidence that caps pick grades (pick_evidence).
-- Generated from the multi-season walk-forward backtests of 2026-10-20.
-- 'market' rows compare against real lines (closing spread / total);
-- 'baseline' rows against a naive model (player's own prior rate, league rate).
-- Rows apply only while detail.engine_version is the champion's engine.
ON CONFLICT (engine, market, source, comparison) DO UPDATE SET n=EXCLUDED.n, seasons=EXCLUDED.seasons, better=EXCLUDED.better,
    worse=EXCLUDED.worse, metric=EXCLUDED.metric, se=EXCLUDED.se, detail=EXCLUDED.detail, updated_at=now();
